"""Live environment chapter rendering from complete retrospective score files only."""
from pathlib import Path
import json

def pages(w, read, table, links, fmt, n, preview):
    base=Path(__file__).resolve().parents[1]/"alfworld"
    a=read("alfworld/results.json") if (base/"results.json").exists() else {}
    x=read("alfworld/transfer_results.json") if (base/"transfer_results.json").exists() else {}
    if not preview and not (a and x):
        raise ValueError("Publication requires both closed ALFWorld cohorts")
    def base_value(method,field,digits=None):
        if not a:return "—"
        z=a["all"][method][field]
        return n(z) if digits is None else fmt(z,digits)
    w.page("Исполняемая среда     /     ALFWorld","Что нужно помнить во время поиска",
           "В частично наблюдаемой квартире агенту приходится исследовать ящики, столы и полки. Среда позволяет увидеть, приводит ли память о прошлых осмотрах к выполнению цели.")
    w.p("Общий программный контроллер видел публичную инструкцию, описание комнаты, допустимые действия и ответы на свои команды. Цель надо выполнить за 50 действий. Агент сохранял текущее состояние манипуляции, включая предмет в руке. Менялось правило выбора следующего места поиска. Число шагов для нерешённой игры при расчёте среднего всегда равно 50.")
    names=[("none","Без учёта осмотренных мест"),("recent","Четыре последних места"),("cursor","Циклический обход от текущей позиции"),("full","Все осмотренные места"),("raw","Все места и частота находок на train"),("rate","Все места и доля находок среди осмотров")]
    table(["Память и выбор места","Решено из 134","Среднее шагов","Повторные осмотры"],[[title,base_value(k,"won"),base_value(k,"mean_capped_steps",2),base_value(k,"repeated_checks")] for k,title in names],[7.8,3.0,3.05,3.25])
    if a:
        z=a["contrasts"]["full-recent"];cur=a["contrasts"]["cursor-full"]
        w.p(f"Полное множество против четырёх последних осмотров изменило исход с поражения на победу в {z['W']} играх, с победы на поражение — в {z['L']}. Изменение среднего числа шагов составило {fmt(z['mean_step_difference'])}. Курсор против полного множества дал {cur['W']} выигранных и {cur['L']} потерянных игр. Проверка кода показала, что перед чтением курсор записывался из уже известной текущей позиции. Эквивалентный обход требует ноль дополнительных записей. Преимущество над вариантом без учёта осмотров включает эффект порядка обхода.")
    else:w.p("Сводные парные исходы будут доступны после закрытия всех траекторий и проверки стартовых состояний.")
    w.h("Как формировалась память об опыте")
    w.p("В 39 обучающих играх получено 875 наблюдений за 1 305 команд. Для 24 последних осмотров исходный журнал не сохранил конечное меню. Независимый повтор тех же игр восстановил пропуск и подтвердил все 875 записей. Сырые числа находок дают преимущество классам мест, которые чаще проверяли. Сглаженная доля равна (находки + 1) / (осмотры + 2). Поэтому сравнение одновременно меняет нормирование и сглаживание. В обоих вариантах доступны одни и те же ранние события. В таблице повторы у полного списка и вариантов с прошлым опытом относятся к разным фазам поиска. Ни одного повторного осмотра внутри той же фазы у этих вариантов не было.")
    if a:
        z=a["contrasts"]["rate-raw"]; fl=z["floor_differences"]
        w.p(f"Нормирование потребовало в среднем на {fmt(-z['mean_step_difference'])} шага меньше, чем сырые частоты. Интервал по четырём планировкам [{fmt(z['floor_resample_steps_interval'][0])}; {fmt(z['floor_resample_steps_interval'][1])}] для разности шагов включает ноль. Все {z['T']} исходов по достижению цели совпали. Восемь из десяти вариантов, включая обычный курсор, достигли цели во всех 134 играх.","Caption")
    links(("ALFWorld, описание среды","https://arxiv.org/abs/2010.03768"),("Зафиксированная версия кода","https://github.com/alfworld/alfworld/tree/aaba6870f86c5be6a08a491f32a50b906227bc3e"))
    w.page("Планировщик     /     ALFWorld","Как модель читает наблюдения о местах",
           "Может ли модель использовать удачные и неудачные поиски, если уже располагает собственным представлением о том, где лежат вещи?")
    w.p("Локальная Qwen3.8-27B Q4_K_M видела класс целевого предмета и доступные классы мест. Она однократно ранжировала их для каждого различного запроса. Дальше тот же программный контроллер выполнял действия. Все четыре условия получили одинаковый набор игр и лимит 50 команд. Текст из прежних комнат был ограничен анонимными счётчиками осмотров и находок.")
    names=[("q_prior","Только исходные знания модели"),("q_shown","Та же модель и релевантные наблюдения"),("q_placebo","Наблюдения о другом предмете"),("q_fused","Ранг модели и фиксированная формула по данным")]
    table(["Как использован прошлый опыт","Решено из 134","Среднее шагов","Повторные осмотры"],[[title,base_value(k,"won"),base_value(k,"mean_capped_steps",2),base_value(k,"repeated_checks")] for k,title in names],[7.8,3.0,3.05,3.25])
    w.h("Предварительно выбранное сравнение")
    if a:
        c=a["contrasts"]["q_shown-q_prior"]; p=a["contrasts"]["q_shown-q_placebo"]; f=a["contrasts"]["q_fused-q_prior"]
        lo,hi=c["floor_resample_steps_interval"]
        w.p(f"Показ релевантных наблюдений модели относительно пустого контекста дал {c['W']} выигранных и {c['L']} потерянных игр. Средняя разность шагов {fmt(c['mean_step_difference'])}, описательный интервал по четырём планировкам [{fmt(lo)}; {fmt(hi)}]. Для сравнения релевантных наблюдений с подложными смена исходов составила {p['W']} / {p['L']}.")
        fr=c["floor_differences"]
        w.p("Показ релевантной памяти относительно пустого контекста сэкономил суммарно 114 и 26 команд на планировках 10 и 424, но добавил 6 и 10 команд на планировках 219 и 308. При сравнении с текстом о другом предмете интервал по шагам составил ["+fmt(p["floor_resample_steps_interval"][0])+"; "+fmt(p["floor_resample_steps_interval"][1])+"]. Интервалы по четырём комнатам имеют описательный характер.")
        w.p(f"Смешивание исходного ранга Qwen с эмпирическими долями дало {f['W']} выигрышей и {f['L']} потерь относительно того же ранга без смешивания. Операция не потребовала дополнительного ответа модели. В основном эксперименте зарегистрировано {a['planner_native_calls']} различных вызовов планировщика, {n(a['planner_usage']['prompt_tokens'])} входных и {n(a['planner_usage']['completion_tokens'])} выходных токенов. Реально исполнено {n(a['eval_steps'])} команд среды в 1 340 эпизодах.")
    else:w.p("Сначала запечатываются планы и весь набор 1 340 парных траекторий. Их проверка даст изменение успеха, среднего числа шагов и разброс по четырём планировкам.")
    w.h("Какие результаты можно сравнивать с MIRIX")
    w.p("Подложные и релевантные данные близки по объёму и форме. Они дали 7 059 и 7 064 входных токена соответственно, пустой вариант — 3 719. У Qwen поиск в первую очередь учитывал номер экземпляра, у правил частоты и доли — оценку класса. Их прямую разницу нельзя целиком приписать способу представления памяти.")
    w.p("Здесь совпадают 134 unseen-игры и лимит 50 команд. В MIRIX‑2.0 языковой агент сам выбирал действия и получал другую форму памяти. Авторы сообщают 76,4% для MIRIX и 69,4% без памяти на GPT‑6 Luna за три прогона. Наш контроллер знает допустимые команды и вызывает Qwen для отдельного шага планирования. Проценты этих систем требуют повторения в общем интерфейсе.")
    links(("MIRIX‑2.0, таблица 10","https://arxiv.org/html/2611.12068v1"))
    w.page("Перенос     /     ALFWorld","Опыт похожих комнат и промахи текущего поиска",
           "В отдельном эксперименте проверялось, повторится ли эффект двух простых правил в новых комнатах и на знакомых планировках.")
    w.p("При чтении памяти прошлые комнаты либо имели равный вес, либо получали вес по сходству видимых классов мест. После неудачного осмотра приоритет других мест того же класса либо сохранялся, либо снижался по заранее заданной формуле. Получились четыре комбинации при том же контроллере и том же обучающем опыте. Модель не вызывалась.")
    def xval(s,k):
        if not x:return "—"
        g=x[s]["all"][k];return f"{g['won']} / {g['n']}  ·  {fmt(g['capped_steps_avg'])}"
    table(["Вариант","Новые планировки¹","Знакомые планировки¹"],[[title,xval("valid_unseen",k),xval("valid_seen",k)] for k,title in [("full","Учёт всех осмотренных мест"),("rate","Глобальная доля находок"),("all_static","Равный вес комнат"),("room_static","Вес по сходству комнат"),("all_miss","Равный вес и учёт промахов"),("room_miss","Сходство комнат и учёт промахов")]],[7.4,4.8,4.9])
    w.p("¹ Успешные игры / все игры и среднее число шагов с ограничением 50. Для unseen два неизменных контроля использованы повторно. В расширении исполнено 1 376 новых эпизодов, всего в двух сериях — 2 716. В 39 тренировочных играх встречаются 30 планировок. Из 76 планировок valid_seen с ними совпали 23, из четырёх valid_unseen — ни одной.")
    if x:
        a1=x["valid_unseen"]["contrasts"]["room_miss-all_static"];b1=x["valid_seen"]["contrasts"]["room_miss-all_static"]
        w.h("Воспроизведение на другом разбиении")
        for label,record,data in [("На новых планировках",a1,x["valid_unseen"]),("На знакомых планировках",b1,x["valid_seen"])]:
            ci=record["cluster_intervals"][1]
            w.p(f"{label} совместное правило против глобальной статической памяти дало {record['W']} выигранных и {record['L']} потерянных игр. Разница по средним шагам {fmt(record['step_difference'])}, описательный кластерный интервал [{fmt(ci[0])}; {fmt(ci[1])}]. Число планировок — {len(data['floors'])}.")
        supported=(a1["step_difference"]<0 and b1["step_difference"]<0)
        w.p("Заранее выбранное направление — уменьшение шагов на обоих разбиениях — "+("воспроизвелось" if supported else "не воспроизвелось")+". Оценивать вклад каждого правила следует по двум отдельным вариантам таблицы. Выбор лучшей строки задним числом потребовал бы независимой проверки.","Caption")
        w.p("При сравнении только с полным списком осмотров без межзадачного опыта совместное правило выглядело бы положительно в обоих разбиениях. Более сильный контроль, который также использует прошлые комнаты, изменил вывод на новых планировках. Там простое сходство комнат без учёта промахов в среднем потребовало 9,43 шага против 9,81 у совместного правила.")
        w.p("Отдельно у простого переноса сглаженной доли находок при том же полном списке посещений получилось −2,39 шага на valid_seen, интервал по комнатам [−3,91; −0,83], и −2,56 на valid_unseen [−4,28; +2,31]. Успех у сравниваемых правил был полным в обоих разбиениях. Этот контроль оценивает добавление опыта при неизменной памяти об осмотрах.")
    else:w.p("Вывод о воспроизведении будет вычислен на обоих полностью закрытых наборах по предварительно выбранному направлению разности числа шагов.")
    links(("Официальный ALFWorld","https://github.com/alfworld/alfworld"))

